primary" x-show="!unitId" @click="edit('units')"><x-icon name="plus"/>Tambah unit</button><button class="btn btn-primary" x-show="unitId" @click="safePlacement()"><x-icon name="plus"/>Tambah anggota</button></div></div><div class="notice flex flex-wrap justify-between items-center gap-4 mb-5"><div><p class="small muted" x-text="unitId?'Kepala Unit':'Kepala Divisi'"></p><strong x-text="(unitId ? unitHead?.head_name : division.head_name) || 'Belum ditetapkan'"></strong></div><button class="btn" @click="safeHead(unitId?'units':'divisions')">Atur kepala</button></div><div x-show="!unitId"><div class="table-wrap"><table class="table"><thead><tr><th>Unit</th><th>Kepala Unit</th><th class="numeric">Karyawan</th><th>Tindakan</th></tr></thead><tbody><template x-for="row in units" :key="row.id"><tr><td><strong x-text="row.name"></strong></td><td x-text="row.head_name || 'Belum ditetapkan'"></td><td class="numeric" x-text="row.employee_count"></td><td><button class="btn btn-small" @click="unitId=row.id">Kelola unit</button></td></tr></template><tr x-show="!units.length"><td colspan="4" class="muted">Belum ada unit aktif. Tambahkan unit pertama.</td></tr></tbody></table></div></div><div x-show="unitId"><div class="toolbar"><div class="field"><label for="organization-search">Cari anggota unit</label><input id="organization-search" type="search" x-model="search" placeholder="Cari nama / NIP…"></div><a class="btn" href="/hc/organization/employees">Buat karyawan baru</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Nama / NIP</th><th>Jabatan</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><template x-for="row in employees" :key="row.id"><tr><td><strong x-text="row.full_name"></strong><span class="subtext" x-text="row.nip"></span></td><td x-text="row.position_name"></td><td><x-badge value="row.is_active?'active':'inactive'"/></td><td><button class="btn btn-small" @click="safePlacement(row)">Pindahkan</button></td></tr></template><tr x-show="!employees.length"><td colspan="4" class="muted">Belum ada anggota sesuai filter. Pilih Tambah anggota untuk menempatkan karyawan.</td></tr></tbody></table></div></div></div></template></div></div><div class="notice mt-4"><strong>Cakupan akses mengikuti struktur</strong>Kepala Divisi melihat unit dalam divisinya. Kepala Unit mengisi nilai anggotanya. Pemindahan tidak mengubah histori Final; perubahan dengan penilaian aktif dapat diblokir.</div></div>
