<dialog x-ref="operation" @click.self="$el.close()"><form class="dialog-body" @submit.prevent="saveOperation()"><div class="dialog-header"><h2 x-text="operation==='placement'?'Atur penempatan karyawan':operation==='head-unit'?'Tetapkan Kepala Unit':'Tetapkan Kepala Divisi'"></h2><button class="icon-button" type="button" @click="$refs.operation.close()" aria-label="Tutup penugasan"><x-icon name="close"/></button></div><div class="stack"><div class="field" x-show="operation==='placement'"><label for="placement-employee">Karyawan</label><select id="placement-employee" x-model="operationForm.employee_id" @change="previewPlacement()" :required="operation==='placement'"><option value="">Pilih karyawan</option><template x-for="employee in lookups.employees.filter(e=>e.is_active)" :key="employee.id"><option :value="employee.id" x-text="employee.full_name+' · '+(employee.unit_name || 'Belum ditempatkan')"></option></template></select></div><div class="field" x-show="operation==='placement'"><label for="placement-unit">Unit tujuan</label><select id="placement-unit" x-model="operationForm.unit_id" :required="operation==='placement'"><option value="">Pilih unit tujuan</option><template x-for="unit in lookups.units" :key="unit.id"><option :value="unit.id" x-text="unit.division_name+' / '+unit.name"></option></template></select></div><div class="field" x-show="operation!=='placement'"><label for="head-user">Akun penanggung jawab</label><select id="head-user" x-model="operationForm.user_id" :required="operation!=='placement'"><option value="">Pilih akun kepala</option><template x-for="user in eligibleHeads" :key="user.id"><option :value="user.id" x-text="user.name+' · '+(user.email || user.login_nip)"></option></template></select><p class="small muted mt-2">Akun harus aktif, memenuhi peran, dan belum memiliki penugasan. Kepala Unit harus terhubung ke karyawan dalam unit ini.</p><a class="brand small underline" href="/hc/organization/users">Kelola akun dan kelayakan peran</a></div><div class="notice" x-show="preview"><strong>Peninjauan dampak</strong><p x-text="(preview?.active_assessments || 0)+' penilaian aktif terkait.'"></p><p x-show="preview?.active_assessments">Selesaikan penilaian aktif sebelum melakukan perubahan organisasi.</p><p x-show="operation==='placement'" x-text="movingEmployee ? 'Asal: '+(movingEmployee.unit_name || 'Belum ditempatkan') : ''"></p><p x-show="operation==='placement' && targetUnit" x-text="targetUnit ? 'Tujuan: '+targetUnit.division_name+' / '+targetUnit.name : ''"></p></div><div class="field"><label for="organization-reason">Alasan perubahan</label><textarea id="organization-reason" x-model="operationForm.reason" required minlength="3" maxlength="5000" placeholder="Tuliskan alasan penugasan atau pemindahan…"></textarea></div><p class="notice notice-error" x-show="operationError" x-text="operationError"></p></div><div class="dialog-footer"><button class="btn" type="button" @click="$refs.operation.close()">Batal</button><button class="btn btn-primary" type="submit" :disabled="!preview || preview.active_assessments>0">Tinjau dan konfirmasi</button></div></form></dialog>
